import sys, time, numpy as np
sys.path.insert(0,'/workspace'); sys.path.insert(0,'/workspace/submission')
from tests_common import make_case, tol
from te.algorithms.formulations.path_based.distributed.worker import solve_worker_proposal

def verify(cap, dem, slots, mode, rho, bias, owned, prop):
    errs=[]
    live=cap>0
    E=len(cap)
    avail={k:[ (slots[k][t] is not None and all(live[e] for e in slots[k][t])) for t in range(len(slots[k]))] for k in owned}
    x={}
    for i,k in enumerate(owned):
        assert len(prop['flow'][i])==len(slots[k]), 'flow width'
        for t,v in enumerate(prop['flow'][i]):
            x[(k,t)]=v
    L=np.zeros(E)
    for (k,t),v in x.items():
        if slots[k][t] is not None:
            for e in slots[k][t]: L[e]+=v
    for e in range(E):
        if not live[e] and L[e]!=0: errs.append(f'load nonzero withdrawn {e}')
        if abs(L[e]-prop['edge_load'][e])>tol(L[e],prop['edge_load'][e]): errs.append(f'load mismatch {e} {L[e]} {prop["edge_load"][e]}')
    R=sum(x.values())
    f=0.5*sum(v*v for v in x.values())+0.5*rho*sum(((L[e]/cap[e]-bias[e])**2 for e in range(E) if live[e]))-(R if mode=='admit' else 0)
    G={}
    for i,k in enumerate(owned):
        if dem[k]<=0: continue
        for t in range(len(slots[k])):
            if not avail[k][t]: continue
            G[(k,t)]=x[(k,t)]+rho*sum(((L[e]/cap[e]-bias[e])/cap[e] for e in slots[k][t]))-(1 if mode=='admit' else 0)
    lam={k:prop['potential'][i] for i,k in enumerate(owned)}
    for i,k in enumerate(owned):
        if dem[k]==0 and lam[k]!=0: errs.append('zero demand potential nonzero')
        if mode=='admit' and lam[k]<0: errs.append('negative admit potential')
        if not (-1e9<=lam[k]<=1e9): errs.append('potential range')
        for t in range(len(slots[k])):
            if dem[k]<=0 or not avail[k][t]:
                if x[(k,t)]!=0: errs.append(f'nonzero on unavailable/zero demand {k} {t}')
            else:
                val=G[(k,t)]+lam[k]
                if val < -tol(val,0): errs.append(f'G+lam viol {k} {t} {val}')
        ssum=sum(x[(k,t)] for t in range(len(slots[k])))
        if mode=='route':
            if abs(ssum-dem[k])>tol(ssum,dem[k]): errs.append(f'route sum {k} {ssum} vs {dem[k]}')
        else:
            if ssum-dem[k]>tol(ssum,dem[k]): errs.append(f'admit sum {k} {ssum} vs {dem[k]}')
        if any(v<-tol(v,0) for v in x.values()): errs.append('negative flow')
    D=f-sum(x[k]*g for k,g in G.items())-sum(dem[k]*lam[k] for k in owned)
    if abs(f-D)>tol(f,D): errs.append(f'gap {abs(f-D)} tol {tol(f,D)} f={f}')
    return errs

def main(n=600, seed0=0):
    rng=np.random.default_rng(11)
    t0=time.time(); bad=0; ninf=0; cnt=0
    for seed in range(seed0, seed0+n):
        nodes,edges,cap,dem,slots=make_case(seed)
        E=len(cap)
        owned=list(range(len(slots)))
        bias=rng.normal(size=E)*0.5*(cap>0)
        rho=float(rng.integers(1,9))
        for mode in ('route','admit'):
            prop=solve_worker_proposal(owned,cap,dem,slots,mode,rho,bias,E)
            cnt+=1
            if prop['status']=='infeasible':
                ninf+=1
                exp=sorted(k for k in owned if dem[k]>0 and not any(slots[k][t] is not None and all(cap[e]>0 for e in slots[k][t]) for t in range(len(slots[k]))))
                if mode!='route' or prop['unroutable']!=exp:
                    print('INFEAS MISMATCH',seed,mode,prop['unroutable'],exp); bad+=1
                continue
            if mode=='route':
                exp=[k for k in owned if dem[k]>0 and not any(slots[k][t] is not None and all(cap[e]>0 for e in slots[k][t]) for t in range(len(slots[k])))]
                if exp: print('should be infeasible',seed,exp); bad+=1
            errs=verify(cap,dem,slots,mode,rho,bias,owned,prop)
            if errs:
                bad+=1
                if bad<8: print('seed',seed,mode,'rho',rho,'errs',errs[:3])
    print('bad',bad,'of',cnt,'infeasible',ninf,'time',round(time.time()-t0,2))
main()
